INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8159, 33205, 'tt0065649', NULL, 'Dodes''ka-den', 'どですかでん', 'movie', 1970, 'https://image.tmdb.org/t/p/w500/gP9pM94ATcZGfKQ3faKy0a3dVIi.jpg', 'https://image.tmdb.org/t/p/original/6CsuEnJUbrHb2xVLgkB4zxb1Kta.jpg', 'On a Tokyo dump’s shantytown edge, interwoven vignettes follow residents scraping by: a boy who “drives” an imaginary trolley, a homeless father and son designing a dream house, a young woman brutalized at home, drunks, schemers, and saints of small kindnesses. Kurosawa crafts a ragged mosaic of hardship, fantasy, and flickers of grace that keep people moving forward.', NULL, NULL, 2.4693, 7.101, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
