INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8161, 63147, 'tt1719634', NULL, 'Snow on tha Bluff', 'Snow on tha Bluff', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/vXGArJcQG14TcLVsmFO8BEEI7Ar.jpg', 'https://image.tmdb.org/t/p/original/o8TJBedg2RGRwzGfSg0qhcSTpYD.jpg', 'When Curtis Snow steals a video camera from some college kids during a dope deal, he gives the camera to his best friend, Pancho, and they start documenting their lives. At first its business as usual for Curtis. He robs dope boys, he runs from the cops, he sells drugs, all while trying to provide for his two-year-old son. But when one of the dealers he ripped off comes for revenge, Curt’s life starts to spiral out of control.', NULL, NULL, 0.9788, 6.3, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
