INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8171, 1630, 'tt0117318', NULL, 'The People vs. Larry Flynt', 'The People vs. Larry Flynt', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/sAgHn7ys6TiVXBDTZ0UBEjinIUk.jpg', 'https://image.tmdb.org/t/p/original/9oxTuL6on1LBalFyzP6cIp6eUwu.jpg', 'Larry Flynt is the hedonistically obnoxious, but indomitable, publisher of Hustler magazine. The film recounts his struggle to make an honest living publishing his girlie magazine and how it changes into a battle to protect the freedom of speech for all people.', NULL, NULL, 7.74, 6.96, 0, 1.0, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8172, 6072, 'tt0118531', NULL, 'One Eight Seven', 'One Eight Seven', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/rPmmyspi1MZBItSvfx40qwep8ow.jpg', 'https://image.tmdb.org/t/p/original/U4NA0YZinyEQ8lJSVW8QPcffTN.jpg', 'When a Brooklyn high school student writes the police code for homicide, 187, inside a textbook owned by teacher Trevor Garfield, Garfield feels threatened. The principal dismisses the incident, but the same student stabs Trevor soon after. Fifteen months later, a physically and emotionally scarred Trevor relocates to California and takes up substitute teaching. To his dismay, his new school is as full of dangerously undisciplined students as his old one—including four Latin Americans and a European American claiming membership in tagging gang K.O.S. (Kappin'' Off Suckers)—driving him over the edge.', NULL, NULL, 3.9266, 6.658, 0, 1.02, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8173, 24951, 'tt0098115', NULL, 'Prancer', 'Prancer', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/g3JfCGX9fgHwmmKFhRzu7BYc29d.jpg', 'https://image.tmdb.org/t/p/original/nJWyiTiZJLJ0XpH0b7nuyc880Xx.jpg', 'Jessica, the daughter of an impoverished apple farmer, still believes in Santa Claus. So when she comes across a reindeer with an injured leg, it makes perfect sense to her to assume that it is Prancer, who had fallen from a Christmas display in town. She hides the reindeer in her barn and feeds it cookies, until she can return it to Santa. Her father finds the reindeer and decides to sell it to the butcher, not for venison chops, but as an advertising display.', NULL, NULL, 2.4335, 6.046, 0, 1.08, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8174, 9745, 'tt0141109', NULL, 'Jack Frost', 'Jack Frost', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/tdSyQJe7vEDcH9kEVqzVcr0O9lS.jpg', 'https://image.tmdb.org/t/p/original/kVM45FdWgirD08xJAwnRRWMC3QL.jpg', 'A father who can''t keep his promises dies in a car accident. One year later, he returns as a snowman, who has one final chance to put things right with his son before he is gone forever.', NULL, NULL, 4.3784, 6.032, 0, 1.04, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8175, 13247, 'tt0251282', NULL, 'A Muppet Family Christmas', 'A Muppet Family Christmas', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/k2t9NMMWRABHvb00ogcA7HjJw2I.jpg', 'https://image.tmdb.org/t/p/original/tvJkMs2bRc9GVRsSz5Mx5FKhfpD.jpg', 'Fozzie Bear surprises his mother on Christmas Eve by bringing the entire Muppet gang to her farm to celebrate the holidays. Doc and his dog Sprocket, who had planned a quiet Christmas, end up joining the Muppets in their holiday activities and preparations. The Sesame Street and Fraggle Rock regulars join the festivities, but to Kermit''s dismay, the only one missing is Miss Piggy, who has been caught in a snowstorm.', NULL, NULL, 2.0556, 6.939, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8176, 13644, 'tt0101301', NULL, 'All I Want For Christmas', 'All I Want For Christmas', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/3Fcyjwyg7Qjp0qUKo4HfoC7JIf.jpg', 'https://image.tmdb.org/t/p/original/nJ0O5fqDzLPz1rPo0s5e0BDfBBY.jpg', 'Siblings Ethan and Hallie O''Fallon plot to get their divorced parents back together in time for Christmas.', NULL, NULL, 1.8816, 5.65, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8177, 59191, 'tt0353393', NULL, 'Eloise at Christmastime', 'Eloise at Christmastime', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/uBm2QXjmBHN10n68MANWoRw8bMu.jpg', 'https://image.tmdb.org/t/p/original/8OAsjAvlf90uKjYicEkfeKu7NaR.jpg', 'Eloise is a precocious but lovable six-year-old girl who lives in New York''s Plaza Hotel. The owner''s daughter is getting married, but Eloise discovers that the fiance has devious plans to defraud kind Rachel! When her true love is revealed to be none other than Eloise''s best friend Bill who works in the kitchen, Eloise goes on a mission to bring about a Christmas miracle and get the starcrossed lovers back together.. will things work out in time for a happy holiday ending?', NULL, NULL, 1.6653, 6.3, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
