INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8200, 9058, 'tt0110737', NULL, 'Only You', 'Only You', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/7mLLANXgUg3bibTiUitDlB0NZcU.jpg', 'https://image.tmdb.org/t/p/original/8uAwA3xnpMyP6etx3JIjFouA4Cl.jpg', 'Two childhood paranormal incidents have convinced schoolteacher Faith Corvatch that her true love is a guy named ''Damon Bradley'', but she has yet to meet him. Preparing to marry podiatrist Dwayne in ten days, Faith receives a phone call from Dwayne''s old classmate Damon Bradley, who is on his way to Venice. She impulsively decides to fly to Italy with the hope of finally encountering the man of her dreams. Accompanying her on the trip is her sister-in-law and best friend Kate, who has just left her husband, Faith''s brother Larry.', NULL, NULL, 5.7077, 6.7, 0, 1.05, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
