INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8214, NULL, NULL, 15, 'Fallout 3', 'Fallout 3', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ycw.jpg', NULL, 'Fallout 3 from the creators of the award-winning Oblivion, featuring one of the most realized game worlds ever created. Create any kind of character you want and explore the open wastes of post-apocalyptic Washington D.C. Every minute is a fight for survival as you encounter Super Mutants, Ghouls, Raiders and other dangers of the Wasteland. Prepare for the future.

The third game in the Fallout series, Fallout 3 is a singleplayer action role-playing game (RPG) set in a post-apocalyptic Washington DC. Combining the horrific insanity of the Cold War era theory of mutually assured destruction gone terribly wrong, with the kitschy naivety of American 1950s nuclear propaganda, Fallout 3 will satisfy both players familiar with the popular first two games in its series as well as those coming to the franchise for the first time.', 'https://www.igdb.com/games/fallout-3', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
