INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8225, 46195, 'tt1436562', NULL, 'Rio', 'Rio', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/4nJxhUknKV8Gqdhov8pU1YWDYfb.jpg', 'https://image.tmdb.org/t/p/original/3vxlXdwBKztOJdgiZ2Qwasl9FY4.jpg', 'Captured by smugglers when he was just a hatchling, a macaw named Blu never learned to fly and lives a happily domesticated life in Minnesota with his human friend, Linda. Blu is thought to be the last of his kind, but when word comes that Jewel, a lone female, lives in Rio de Janeiro, Blu and Linda go to meet her. Animal smugglers kidnap Blu and Jewel, but the pair soon escape and begin a perilous adventure back to freedom -- and Linda.', NULL, NULL, 15.6785, 6.771, 0, 2.24, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8226, 86943, 'tt8001788', NULL, 'Girls from Ipanema', 'Coisa Mais Linda', 'tv', 2019, 'https://image.tmdb.org/t/p/w500/w3S7O45AR4kEHoGpmGy9NZQ24KH.jpg', 'https://image.tmdb.org/t/p/original/iASz7AOL3GzbTjOBJOsWzONBhaB.jpg', 'A 1950s housewife goes to Rio de Janeiro to meet up with her husband, only to learn he''s deserted her, but decides to stay and open a bossa nova club.', NULL, NULL, 2.8351, 6.7, 0, 2.04, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8227, 698, 'tt0079574', NULL, 'Moonraker', 'Moonraker', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/6LrJdXNmu5uHOVALZxVYd44Lva0.jpg', 'https://image.tmdb.org/t/p/original/mrDC5DLx2wljt4HZGwgkmqlzfcF.jpg', 'After Drax Industries'' Moonraker space shuttle is hijacked, secret agent James Bond is assigned to investigate, traveling to California to meet the company''s owner, the mysterious Hugo Drax. With the help of scientist Dr. Holly Goodhead, Bond soon uncovers Drax''s nefarious plans for humanity, all the while fending off an old nemesis, Jaws, and venturing to Venice, Rio, the Amazon...and even outer space.', NULL, NULL, 7.5482, 6.2, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8228, 8833, 'tt0087481', NULL, 'Double Trouble', 'Non c''è due senza quattro', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/eARQ5FY1Z1mSPgoyLJKJdl75RxJ.jpg', 'https://image.tmdb.org/t/p/original/ualoh6ldiiAZU4A1thzmF58mGaW.jpg', 'A stuntman and a saxophonist stand in for two billionaires threatened by killers.', NULL, NULL, 3.4591, 7.019, 0, 1.02, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8229, 237791, 'tt1702014', NULL, 'The Way He Looks', 'Hoje Eu Quero Voltar Sozinho', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/2BhhlAYwKvONGW7tr16ZhnD0sym.jpg', 'https://image.tmdb.org/t/p/original/wMDg5cm1xIieCTINQo6drZWIy8n.jpg', 'Leonardo is a blind teenager dealing with an overprotective mother while trying to live a more independent life. To the disappointment of his best friend, Giovana, he plans to go on an exchange program abroad. When Gabriel, a new student in town, arrives at their classroom, new feelings blossom in Leonardo making him question his plans.', NULL, NULL, 3.0474, 7.926, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8230, 40823, 'tt0367859', NULL, 'The Man Who Copied', 'O Homem Que Copiava', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/3RsEkEdLEFd0Q5HThqMd4X8tYZk.jpg', 'https://image.tmdb.org/t/p/original/fN4OThflKQ8ZT1w2qRRIJmLejKk.jpg', 'A young photocopier operator becomes infatuated with his neighbor and, unable to afford anything from her shop, turns to shady schemes to make money.', NULL, NULL, 1.0385, 7.509, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8231, 310569, 'tt3742378', NULL, 'The Second Mother', 'Que Horas Ela Volta?', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/u1tDQun2iJAzersd94S8P47WEOL.jpg', 'https://image.tmdb.org/t/p/original/9h5BsxRmxLAvASADo2VcTlTUdb0.jpg', 'After leaving her daughter Jessica in a small town in Pernambuco to be raised by relatives, Val spends the next 13 years working as a nanny to Fabinho in São Paulo. She has financial stability but has to live with the guilt of having not raised Jessica herself. As Fabinho’s university entrance exams approach, Jessica reappears in her life and seems to want to give her mother a second chance. However, Jessica has not been raised to be a servant and her very existence will turn Val’s routine on its head. With precision and humour, the subtle and powerful forces that keep rigid class structures in place and how the youth may just be the ones to shake it all up.', NULL, NULL, 3.0263, 8.018, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8232, 42031, 'tt0089297', NULL, 'Hour of the Star', 'A Hora da Estrela', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/wjjq98Og5LTIpfBZri4giCs0xvx.jpg', 'https://image.tmdb.org/t/p/original/nIKGIOYyOEm3UE31CAIpFUPh8Pr.jpg', 'Macabéa has just moved to the big city after her aunt, who raised her, died. She gets a job as a typist and moves into a boarding house with three other women. In her spare time, she listens to a radio station called Time; on Sundays, she likes to ride the metro. Then she meets Olímpico, a northeasterner like herself, who has dreams of becoming a congressman.', NULL, NULL, 1.643, 7.273, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8233, 52345, 'tt0367975', NULL, 'Lisbela and the Prisoner', 'Lisbela e o Prisioneiro', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/raCdo5Hjpd3uXbpSd1JZ7tEyE31.jpg', 'https://image.tmdb.org/t/p/original/eAOOeqa14oCxgdKxLvpDYxCJhqQ.jpg', 'Lisbela is a young woman who loves going to the movies. Leléu is a con man, going from town to town selling all sort of things and performing as master of ceremonies for some cheesy numbers, such as the woman who gets transformed into a gorilla. He gets involved with Linaura, a sexy and beautiful woman who happens to be the wife of the most frightening hitman of the place. The hitman finds out his wife''s affair and goes after Leléu, who has to leave in a hurry. In another town, he meets and falls instantly in love with Lisbela, who is engaged to Douglas, a hillbilly who tries hard to pass for a cosmopolitan Rio de Janeiro dweller.', NULL, NULL, 0.305, 7.831, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8234, 20268, 'tt1280567', NULL, 'Last Stop 174', 'Última Parada 174', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/qvSZA7HIJMelYSaQ7ObBCylDnsX.jpg', 'https://image.tmdb.org/t/p/original/xhK1B9ilRCvOKdEs6JofFQj5JDf.jpg', 'Sandro was a boy who loved to sing rap, to kiss, to stare the statue of Christ the Redeemer and dreamed to go visit Copacabana. Growing up on streets, the story culminates at the infamous episode of 12th June 2000, when Sandro hijacked bus 174.', NULL, NULL, 1.4942, 7.212, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8235, 7343, 'tt0870090', NULL, 'City of Men', 'Cidade dos Homens', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/eVqTDE0seY23gw9aCpBmWTjIPdc.jpg', 'https://image.tmdb.org/t/p/original/1mJFeIf51DKAz84895htRmRzhs7.jpg', 'Best buddies Acerola and Laranjinha, about to turn 18, discover things about their missing fathers'' pasts which will shatter their solid friendship, in the middle of a war between rival drug gangs from Rio''s favelas.', NULL, NULL, 2.3358, 7.044, 0, 1.02, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8236, 47931, 'tt1555149', NULL, 'Elite Squad: The Enemy Within', 'Tropa de Elite 2', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/c7yCrf3PTSdp6RMGktZQhzFcFFM.jpg', 'https://image.tmdb.org/t/p/original/tmowA51oykuOdiyqRCP0jGYU1mB.jpg', 'After a bloody invasion of the BOPE in the High-Security Penitentiary Bangu 1 in Rio de Janeiro to control a rebellion of interns, the Lieutenant-Colonel Roberto Nascimento and the second in command Captain André Matias are accused by the Human Right Aids member Diogo Fraga of execution of prisoners. Matias is transferred to the corrupted Military Police and Nascimento is exonerated from the BOPE by the Governor.', NULL, NULL, 4.8099, 7.85, 0, 1.02, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8237, 211166, 'tt1456606', NULL, 'Rio, I Love You', 'Rio, Eu Te Amo', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/e4MEGQlEE7VojlBpwaJvjMcXJPg.jpg', 'https://image.tmdb.org/t/p/original/fee4Wfz9zWhRO7ybfUMIYSCZg8q.jpg', 'The third episode of the Cities of Love franchise, Rio, I Love You is an anthology, created by 10 visionary directors from across the globe. The story line of each segment focuses on an encounter of love in a different neighborhood of the city, demonstrating the distinctive qualities and character of that location. The film serves to bridge gaps between cultures, educating and entertaining the audience, while celebrating unique and universal expressions of love.', NULL, NULL, 2.3695, 4.796, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8238, 15588, 'tt1167660', NULL, 'OSS 117: Lost in Rio', 'OSS 117 : Rio ne répond plus', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/rhv06T3gTFOShIVkQ0UipZFIyDw.jpg', 'https://image.tmdb.org/t/p/original/t1LMwZqFXjoa7KM4QWGZxmUYD4J.jpg', 'In 1967, OSS 117 is sent to Brazil in order to retrieve a microfilm list of French Nazi sympathizers, only to once again unknowingly set foot into a bigger international intrigue.', NULL, NULL, 2.7754, 7.097, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8239, 2357, 'tt0499603', NULL, '10 Items or Less', '10 Items or Less', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/2MBxFTeRe4m7DC49PmIkMXMjMEO.jpg', 'https://image.tmdb.org/t/p/original/uXFmUOVUvw2coUYSCQu3Z4AnKCd.jpg', 'An actor who is considering the role of a supermarket manager arrives at a grocery store on the outskirts of Los Angeles to do some field research. He subsequently becomes stranded, without a car or cell phone, and accepts a ride home with Scarlet, a cashier who is about to interview for a new job. The actor rediscovers the essence of his craft while helping Scarlet gain the confidence she needs to change her life.', NULL, NULL, 3.1601, 6.219, 0, 1.0, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8240, 46153, 'tt1685484', NULL, 'Wagnaria!!', 'WORKING!!', 'tv', 2010, 'https://image.tmdb.org/t/p/w500/5Wnj5n0qPg5lVxTBYAnWuuxoiwf.jpg', 'https://image.tmdb.org/t/p/original/1IVzP2uOv1txYbHempW2VsTF5KW.jpg', 'Set in a family restaurant in Hokkaido, the northern prefecture of Japan, 16-year-old high school student Sōta Takanashi works part-time along with his strange co-workers: Popura Taneshima, a high school girl who—despite being a year older than Sōta—is easily mistaken for a elementary/middle schooler, and Kyoko Shirafuji, the 28-year-old store manager who does not bother to do any work at all.', NULL, NULL, 20.198, 8.086, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
