INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8246, 286791, 'tt37499375', NULL, 'Digimon Beatbreak', 'DIGIMON BEATBREAK', 'tv', 2025, 'https://image.tmdb.org/t/p/w500/qcy74ZdijvhaIyiPKFVZJZZrpJt.jpg', 'https://image.tmdb.org/t/p/original/7Sz41DFZZpnkbLVJFKSF1cbCMyz.jpg', 'Tomoro Tenma lives in a world where human thoughts and emotions, known as e-Pulse, power AI devices called Sapotama. But when Digimon begin materializing from Sapotama and feeding on e-Pulse, society begins to fracture. After Gekkomon appears from his device, Tomoro joins Glowing Dawn, a secret team investigating rogue Digimon and the dark truth of a system both fueled and corrupted by emotion.', NULL, NULL, 18.1716, 7.8, 0, 1.22, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
