INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8293, 10660, 'tt0110167', NULL, 'It Could Happen to You', 'It Could Happen to You', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/6UOaeLDOdwwTMQtbl5YL6EGjqy0.jpg', 'https://image.tmdb.org/t/p/original/rHqIKBrvmRTExmi7XN31OjRSPKT.jpg', 'Charlie Lang is a simple, kindhearted New York City cop. When he realizes he has no money to tip waitress Yvonne Biasi, Lang offers her half the winnings of his lottery ticket. Amazingly, the ticket happens to be a winner, in the sum of $4 million. True to his word, Lang proceeds to share the prize money with Biasi, which infuriates his greedy wife, Muriel. Not content with the arrangement, Muriel begins scheming to take all the money.', NULL, NULL, 5.9876, 6.739, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8294, 787326, 'tt0394853', NULL, 'The Petrified Forest', 'The Petrified Forest', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/j3lqsmOdKiHtLRoPw4wa0yRGNYE.jpg', 'https://image.tmdb.org/t/p/original/e9wq9I3w8YnskLaxs7ZK8auiNNJ.jpg', 'Gabrielle Maple works in a dusty desert gas station-café, but yearns for the life of an artist in France, knowing there must be something finer than the provincial dead-end she is trapped in. A hitch-hiking writer, the disillusioned Alan Squier, appears and revitalizes her dreams of a better place, and finds his own sense of worth refreshed by this vital young girl. When Duke Mantee and his gang, wanted killers, show up and take hostages, Gabrielle falls in love with the poetic Alan, and Squier begins to see a way to give Gabby the life she deserves.', NULL, NULL, 0.8505, 6.8, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
