INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8311, 37233, 'tt0106918', NULL, 'The Firm', 'The Firm', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/kFexXCzidkm4LwlgZqxsJsDQB5v.jpg', 'https://image.tmdb.org/t/p/original/jlUTfePS1XRyMpgZvjFvDk7yEi0.jpg', 'Mitch McDeere is a young man with a promising future in Law. About to sit his Bar exam, he is approached by ''The Firm'' and made an offer he doesn''t refuse. Seduced by the money and gifts showered on him, he is totally oblivious to the more sinister side of his company. Then, two Associates are murdered. The FBI contact him, asking him for information and suddenly his life is ruined. He has a choice - work with the FBI, or stay with the Firm. Either way he will lose his life as he knows it. Mitch figures the only way out is to follow his own plan...', NULL, NULL, 10.7154, 6.7, 0, 2.07, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8312, 14914, 'tt1054588', NULL, 'Flash of Genius', 'Flash of Genius', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/14gyR9JMVfngQlolzD2N365ZeRz.jpg', 'https://image.tmdb.org/t/p/original/ApZcctYdXNkRTjQH5Yr6eFMkmYk.jpg', 'In this David vs. Goliath drama based on a true story, college professor Robert Kearns goes up against the giants of the auto industry when they fail to give him credit for inventing intermittent windshield wipers. Kearns doggedly pursues recognition for his invention, as well as the much-deserved financial rewards for the sake of his wife and six kids.', NULL, NULL, 2.5233, 6.6, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8313, 462, 'tt0195685', NULL, 'Erin Brockovich', 'Erin Brockovich', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/eMs20iUQyZVs05Ck7Q0LNnRsstr.jpg', 'https://image.tmdb.org/t/p/original/3HmLKhahTxX2ALTWlagr92pZrU7.jpg', 'A twice-divorced mother of three who sees an injustice, takes on the bad guy and wins -- with a little help from her push-up bra. Erin goes to work for an attorney and comes across medical records describing illnesses clustered in one nearby town. She starts investigating and soon exposes a monumental cover-up.', NULL, NULL, 11.2888, 7.428, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8314, 7777, 'tt1235547', NULL, 'Better Off Ted', 'Better Off Ted', 'tv', 2009, 'https://image.tmdb.org/t/p/w500/tvmafNGqMFA03fJcbUXxjgzSToX.jpg', 'https://image.tmdb.org/t/p/original/mpUcBHfzKpSo72rwo2EaaGkeSX1.jpg', 'Ted, a successful but morally conscious man, runs a research and development department at a morally questionable corporation, Veridian Dynamics. No achievement is too far fetched and no invention too unorthodox for Veridian. Ted loves his seemingly perfect job; he loves his superhuman boss, Veronica, and colleagues Lem, Phil and Linda, but he''s starting to take a closer look at the company''s extremely questionable practices... especially when they try to cryogenically freeze one of Ted''s scientists for testing purposes.', NULL, NULL, 6.1893, 7.606, 0, 1.03, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8315, NULL, NULL, 42, 'Deus Ex: Invisible War', 'Deus Ex: Invisible War', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coboyb.jpg', NULL, 'Several religious and political factions see an opportunity to re-shape a worldwide government to their agendas. In this techno-nightmare, take part in the dark struggle to raise the world from its own ashes.

This dynamic and innovative 1st person-action/adventure brings a level of reality unprecedented in a videogame. Biotech modifications allow players to see through walls, leap 40 feet into the air, regenerate critical body damage or render yourself radar invisible. Globe-hop to real world locations such as Seattle, Antarctica, and Cairo.', 'https://www.igdb.com/games/deus-ex-invisible-war', '["Xbox", "PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8316, NULL, NULL, 517, 'F.E.A.R.', 'F.E.A.R.', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1utk.jpg', NULL, '"F.E.A.R." (First Encounter Assault Recon) is a critically acclaimed first-person shooter game released in 2005, developed by Monolith Productions and published by Sierra Entertainment. Blending psychological horror with intense combat, "F.E.A.R." puts players in the role of a point man in a special forces team tasked with containing a mysterious and powerful paranormal threat. The game''s advanced AI, atmospheric storytelling, and impressive graphics create a deeply immersive experience. Players must navigate through dark, foreboding environments, battling both human enemies and supernatural entities while uncovering the dark secrets behind the paranormal phenomena. Renowned for its tense atmosphere, dynamic firefights, and haunting narrative, "F.E.A.R." stands out as a landmark title in the horror shooter genre.', 'https://www.igdb.com/games/f-e-a-r', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8317, NULL, NULL, 116, 'Star Wars: Knights of the Old Republic', 'Star Wars: Knights of the Old Republic', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tmz.jpg', NULL, 'Choose Your Path! Set 4,000 years before the Galactic Empire, you are the last hope for the Jedi Order and the Republic - can you master the ways of the Force to become their savior? Or will you fall to the dark side and achieve ultimate power? Hero, villain, peacekeeper, or chaos-bringer... you and your party will determine the fate of the galaxy!

Star Wars: Knights of the Old Republic is a role-playing video game. Players will be able to create their own characters and be able to choose what gender, appearance, class, skills, attributes, and feats they have throughout the game - no two characters will be the same!', 'https://www.igdb.com/games/star-wars-knights-of-the-old-republic', '["Xbox", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Nintendo Switch"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8318, NULL, NULL, 3750, 'Quantum Break', 'Quantum Break', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8gsr.jpg', NULL, 'Fix Time Before It Destroys Everything!

When time breaks, catastrophe becomes your playground. As hero Jack Joyce, you''ll fight your way through epic disasters that stutter back and forth in time. But surviving this unstable world--and halting the end of time itself--is only possible by mastering your new time powers.', 'https://www.igdb.com/games/quantum-break', '["PC (Microsoft Windows)", "Xbox One"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
