INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8340, 26126, 'tt0236157', NULL, 'Disco Pigs', 'Disco Pigs', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/cvc0ufpTy8jdazickHhtbrcx3rS.jpg', 'https://image.tmdb.org/t/p/original/2xnCNfAI53k1JQL4a42AVb7McXQ.jpg', 'Pig and Runt born on the same day, in the same hospital, moments apart. Twins, all but by bloodline. Inseparable from birth, they are almost telepathic. They are one, needing no one else, inhabiting a delicate, insular and dangerous world where they make their own rules and have their own language. But days before their 17th birthday the balance of their world begins to shift. Pig''s sexual awakening and jealousy begins to threaten their private universe.', NULL, NULL, 1.4259, 5.7, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8341, 4806, 'tt0163187', NULL, 'Runaway Bride', 'Runaway Bride', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/wzivR0yWJStVdhcl0A5rQvVdTQ7.jpg', 'https://image.tmdb.org/t/p/original/kvZxYVwy75O35YqvkHztYijFVRE.jpg', 'Having already left three grooms at the altar, Maggie Carpenter is branded "the runaway bride" by jaded New York journalist Ike Graham. But, after his facts are called into question, Ike races to Maggie''s hometown to save his reputation and report on her upcoming fourth trip down the aisle – during which he''s convinced she''ll run again. Though he''s there on a muckraking mission, Ike can''t help but fall for this breathtaking heartbreaker.', NULL, NULL, 8.1091, 6.1, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
