INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8386, 1199869, 'tt28088571', NULL, 'Eye for an Eye', 'Eye for an Eye', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/lpepbfVziHJLhVoxTEKs8ok00iu.jpg', 'https://image.tmdb.org/t/p/original/tTDfDHqGkRgBTL4Tw8mU0iwkW8T.jpg', 'Anna, grieving the sudden death of her parents, relocates from New York to a small Florida town to live with the grandmother she has never met. Isolated, vulnerable, and in need of friends, she finds brief solace in the company of two local teens. But when she becomes complicit to their unforgivable act of violence, she finds herself ensnared by Mr. Sandman – the twisted soul of a tormented child who haunts bullies’ dreams before feasting on their eyeballs when they finally wake - Anna must right her wrong before becoming a victim of this gruesome curse.', NULL, NULL, 3.317, 5.9, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
