INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8388, 88557, 'tt6532868', NULL, 'Gogol', 'Гоголь', 'tv', 2019, 'https://image.tmdb.org/t/p/w500/rmXPvO7lPIxQqZdxIgdsr6rRI0r.jpg', 'https://image.tmdb.org/t/p/original/hd2bUHzkJPpjqyrmzcGp11GezKY.jpg', 'The year 1829. Nikolay Gogol, a young Third Section clerk, is desperate: his own books seem shallow and mediocre, so he keeps buying entire print runs just to burn them all. He is suffering from violent epileptic seizures and struggles to keep on working. Investigator Yakov Guro accidentally witnesses one such fit and realizes that Gogol''s visions contain clues that could help solve actual crimes. Together, Gogol and Guro take on a particularly weird and baffling case that brings them to a small village of Dikanka, where everyone has a huge secret to hide.', NULL, NULL, 2.272, 4.333, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
