INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8398, 24021, 'tt1325004', NULL, 'The Twilight Saga: Eclipse', 'The Twilight Saga: Eclipse', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/dK4Gi1UdMiHzHc7r7CZQG4IQ9Sr.jpg', 'https://image.tmdb.org/t/p/original/oguoQWtQJcqIkmmUNbe3CmLx6AP.jpg', 'Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob, knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.', NULL, NULL, 14.7271, 6.19, 0, 1.20266666666666672e+01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8399, 71884, 'tt5615840', NULL, 'Alone Together', 'Alone Together', 'tv', 2018, 'https://image.tmdb.org/t/p/w500/x7aC2jYL9brQlasj67TV1DxQL4Q.jpg', 'https://image.tmdb.org/t/p/original/uVOw766bNqwSXSsTQLX0lekZ7Bu.jpg', 'Esther and Benji are platonic best friends who want nothing more than to be accepted by the vain and status-obsessed culture of Los Angeles. Despite their sometimes contentious relationship, when push comes to shove, they’ve got each other’s back … And they have nobody else to hang out with.', NULL, NULL, 5.1628, 6.118, 0, 8.06, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
