INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8402, 34524, 'tt1567432', NULL, 'Teen Wolf', 'Teen Wolf', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/wjKBTcNy1xihmExqJI8kM2qvavP.jpg', 'https://image.tmdb.org/t/p/original/1F2RnXLc0fmRt7iWfBK4mNVsjno.jpg', 'Scott McCall, a high school student living in the town of Beacon Hills has his life drastically changed when he''s bitten by a werewolf, becoming one himself. He must henceforth learn to balance his problematic new identity with his day-to-day teenage life. The following characters are instrumental to his struggle: Stiles, his best friend; Allison, his love interest who comes from a family of werewolf hunters; and Derek, a mysterious werewolf with a dark past. Throughout the series, he strives to keep his loved ones safe while maintaining normal relationships with them.', NULL, NULL, 47.2246, 8.444, 0, 6.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8403, 484437, 'tt6198946', NULL, 'The Hole in the Ground', 'The Hole in the Ground', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/7DMRJzH9AwpSN5D19cExAB9vDZW.jpg', 'https://image.tmdb.org/t/p/original/wTnFy6B5QCeRgjgCGBGlZaDESJ1.jpg', 'Trying to escape her broken past, Sarah O’Neill is building a new life on the fringes of a backwood rural town with her young son Chris. A terrifying encounter with a mysterious neighbour shatters her fragile security, throwing Sarah into a spiralling nightmare of paranoia and mistrust, as she tries to uncover if the disturbing changes in her little boy are connected to an ominous sinkhole buried deep in the forest that borders their home.', NULL, NULL, 3.6379, 5.65, 0, 6.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
