INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8421, NULL, NULL, 19561, 'Days Gone', 'Days Gone', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co94bn.jpg', NULL, 'Days Gone is an open-world action-adventure game developed by Bend Studio and published by Sony Interactive Entertainment. Released in April 2019 for PlayStation 4 and later for PC in May 2021, the game is set in a post-apocalyptic world where players control Deacon St. John, a drifter and bounty hunter navigating a landscape overrun by "Freakers," zombie-like creatures created by a global pandemic.

The gameplay focuses on exploration, combat, and survival elements, with players able to use various weapons, craft supplies, and upgrade Deacon’s motorcycle, essential for travelling across the vast and hostile environment. Days Gone combines narrative-driven missions with an open world filled with dynamic events, enemy camps, and environmental challenges.', 'https://www.igdb.com/games/days-gone', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
