INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8459, 814, '', NULL, 'Hornblower', 'Hornblower', 'tv', 1998, 'https://image.tmdb.org/t/p/w500/wF4O8zmo2O0B6dQpzTDYruKOpcA.jpg', 'https://image.tmdb.org/t/p/original/jJmouAOqrPLYQJz3Bqf7GbcVXwE.jpg', 'Set during the 18th century Napoleonic Wars, Horatio Hornblower, a young and shy midshipman, rises through the ranks to become an admiral.', NULL, NULL, 7.9538, 7.757, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
