INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8462, 86941, 'tt7660970', NULL, 'The North Water', 'The North Water', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/9CM0ca8pX1os3SJ24hsIc0nN8ph.jpg', 'https://image.tmdb.org/t/p/original/8IC1q0lHFwi5m8VtChLzIfmpaZH.jpg', 'Henry Drax is a harpooner and brutish killer whose amorality has been shaped to fit the harshness of his world, who will set sail on a whaling expedition to the Arctic with Patrick Sumner, a disgraced ex-army surgeon who signs up as the ship’s doctor. Hoping to escape the horrors of his past, Sumner finds himself on an ill-fated journey with a murderous psychopath. In search of redemption, his story becomes a harsh struggle for survival in the Arctic wasteland.', NULL, NULL, 6.8251, 7.354, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8463, 109939, 'tt11000902', NULL, 'Our Flag Means Death', 'Our Flag Means Death', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/mP9OYUoZWod61G8gnsZ5TX1qft.jpg', 'https://image.tmdb.org/t/p/original/uDM0qsZ1q1C82Se2RzVj8I8ufhC.jpg', 'After trading in the seemingly charmed life of a gentleman for one of a swashbuckling buccaneer, Stede Bonnet becomes captain of the pirate ship Revenge. Struggling to earn the respect of his potentially mutinous crew, Stede’s fortunes change after a fateful run-in with the infamous Captain Blackbeard. Stede and crew attempt to get their ship together and survive life on the high seas.', NULL, NULL, 10.9788, 7.522, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8464, 42242, 'tt0075294', NULL, 'Swashbuckler', 'Swashbuckler', 'movie', 1976, 'https://image.tmdb.org/t/p/w500/yeC8gs83BJfs1NENk5sPNyXGGxm.jpg', 'https://image.tmdb.org/t/p/original/eAjww5OTXdHmJJX6M7LwPnC4dRC.jpg', 'A pirate and a hot-tempered noblewoman join forces to protect Jamaica from a tyrant.', NULL, NULL, 2.1769, 6.2, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8465, 12120, 'tt0095687', NULL, 'My Stepmother Is an Alien', 'My Stepmother Is an Alien', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/SIt5FbgvoxlZr8ay3cfi79pV6z.jpg', 'https://image.tmdb.org/t/p/original/qN231DYaVUdEnFUHHPJ0kgpuV82.jpg', 'Trying to rescue her home planet from destruction, a gorgeous extraterrestrial named Celeste arrives on Earth and begins her scientific research. She woos quirky scientist Dr. Steve Mills, a widower with a young daughter. Before long, Celeste finds herself in love with Steve and her new life on Earth, where she experiences true intimacy for the first time. But when she loses sight of her mission, she begins to question where she belongs.', NULL, NULL, 6.1375, 5.801, 0, 1.10100000000000015e+01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8466, 11693, 'tt0997147', NULL, 'Big Man Japan', '大日本人', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/pT5ze3fjW8rYPVtqDyHSRNExHTq.jpg', 'https://image.tmdb.org/t/p/original/dCZ7RhOIM1E0NEkowGNzDyFYw8K.jpg', 'Daisato, a second-rate, third-generation superhero, annoys his neighbors with the noise and destruction he causes on the job. But a heroic public image is the least of his concerns. Besides defending Japan from bizarre monsters, he must deal with an agent seeking to brand him with ads, a superhero grandfather with Alzheimer''s and a family embarrassed by his incompetence.', NULL, NULL, 1.5559, 6.026, 0, 10.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8467, 82401, 'tt0186910', NULL, 'Can of Worms', 'Can of Worms', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/cyQfx4kHTbuFdm6OEQTDrMV22Ko.jpg', 'https://image.tmdb.org/t/p/original/h9tOfwccsf1hYZi6izEbT1NX86Z.jpg', 'A teen is visited by aliens after he broadcasts a message into space.', NULL, NULL, 2.1449, 4.76, 0, 12.0125, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8468, 9849, 'tt0120764', NULL, 'My Favorite Martian', 'My Favorite Martian', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/pOp4xriDEFUy2uN0BfnHJcjzqWt.jpg', 'https://image.tmdb.org/t/p/original/1viDPGEPpEZBVwuIotnaXBQNyGQ.jpg', 'Ambitious television reporter Tim O''Hara stumbles upon a martian whose spaceship has accidentally crashed on Earth. Thinking this is his ticket to a Pulitzer Prize, Tim makes plans to expose the martian, who, posing as Tim''s Uncle Martin, takes human form and has plans of his own. In fact, all of Tim''s efforts to divulge the truth are systematically thwarted by the resourceful alien, who ultimately recruits Tim to help him repair his ship for a return to Mars.', NULL, NULL, 3.7252, 5.669, 0, 8.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8469, NULL, NULL, 4497, 'Star Control', 'Star Control', 'game', 1990, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rei.jpg', NULL, 'Star Control is a science-fiction wargame which pits the forces of The Alliance of Free Stars against those of the predatory Ur-Quan Hierarchy. The game is designed so that you can ease into play, familiarizing yourself with menus, options, and player controls. The Alliance and Hierarchy each possess seven different types of warships. Each vessel has its own maneuvering and firing characteristics, plus a unique special power that you can employ when circumstances dictate.

Mankind is about to be wiped off the face of the galactic map. A savage clutch of alien races called the Ur-Quan Hierachy has become the “evil empire” of the 27th century- ruthlessly invading interstellar neighbors. Humanity is next on their list. Your job is to make sure that they don’t succeed. The entire Alliance of Free Stars battlefleet awaits your orders.', 'https://www.igdb.com/games/star-control', '["Commodore C64/128/MAX", "Sega Mega Drive/Genesis", "DOS", "Amiga"]', NULL, NULL, 0, 10.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8470, NULL, NULL, 204618, 'High on Life', 'High on Life', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co67qo.jpg', NULL, 'From the mind of Justin Roiland (Rick and Morty, Solar Opposites) comes High On Life. Humanity is being threatened by an alien cartel who wants to use them as drugs. It’s up to you to rescue and partner with charismatic, talking guns, take down Garmantuous and his gang, and save the world!', 'https://www.igdb.com/games/high-on-life', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 8.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8471, 777411, 'tt7645334', NULL, 'Landscape with Invisible Hand', 'Landscape with Invisible Hand', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/cnXvfZrj1azU5Rvbb8D7Fz0wkyt.jpg', 'https://image.tmdb.org/t/p/original/pUuaYiqrAchLpEaE0KwIAB1wMD8.jpg', 'Years into a benevolent alien occupation, mankind is still adjusting to its new overlords. Their technology initially held promise for global prosperity, but rendered most human jobs – and steady income – obsolete. When two teenagers discover the aliens are fascinated with human love and will pay for access to it, they decide to livestream their romance to make extra cash for their families.', NULL, NULL, 2.7046, 5.919, 0, 7.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8472, 22049, 'tt0079946', NULL, 'Starcrash', 'Starcrash', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/npJt35Q36aGcTYpcg9epbwQIIkz.jpg', 'https://image.tmdb.org/t/p/original/tyNMdZ79VpDsX6y0oSqirJlYJNi.jpg', 'A pair of smugglers manage to pick up a castaway while running from the authorities, who turns out to be the only survivor from a secret mission to destroy a mysterious superweapon designed by the evil Count Zartharn. The smugglers are soon recruited by the Emperor to complete the mission, as well as to rescue the Emperor''s son, who has gone missing.', NULL, NULL, 2.6685, 4.3, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8473, 3786, 'tt0077278', NULL, 'Buck Rogers in the 25th Century', 'Buck Rogers in the 25th Century', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/up1T1QGSSCfoyuCra0Qnv2yItFt.jpg', 'https://image.tmdb.org/t/p/original/7lKSjFPFyTiigyJzfT70ILH7flc.jpg', 'Capt. William "Buck" Rogers is a jovial space cowboy who is accidentally time-warped from 1987 to 2491. Earth is engaged in interplanetary war following a global holocaust, and Buck''s piloting skills make him an ideal starfighter recruit for the Earth Defense Directorate.', NULL, NULL, 2.2427, 6.1, 0, 1.01, '2026-08-08 02:23:49', '2026-08-08 02:23:49');
UPDATE "recommendations" SET "tmdb_id"=591538, "imdb_id"='tt10095582', "igdb_id"=NULL, "title"='The Tragedy of Macbeth', "original_title"='The Tragedy of Macbeth', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/tDNJEhcLbX3jIk3BMCur9pCdaVD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lMjY6kMBOHhloz2Ul16fLJn8xuw.jpg', "overview"='Macbeth, the Thane of Glamis, receives a prophecy from a trio of witches that one day he will become King of Scotland. Consumed by ambition and spurred to action by his wife, Macbeth murders his king and takes the throne for himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.66, "vote_average"=6.918, "is_ambiguous"=0, "evidence_score"=1.22616666666666667e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=3;
