UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=1877, "title"='Cyberpunk 2077', "original_title"='Cyberpunk 2077', "media_type"='game', "release_year"=2020, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/coaih8.jpg', "backdrop_url"=NULL, "overview"='Cyberpunk 2077 is an open-world action-adventure game set in Night City, a sprawling metropolis driven by power, glamour, and body modification. Players assume the role of V, a mercenary outlaw in pursuit of a unique implant that holds the key to immortality. The game allows extensive customization of cyberware, skills, and playstyle. Choices made throughout the journey influence both the narrative and the world.', "external_url"='https://www.igdb.com/games/cyberpunk-2077', "platforms"='["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=6.3825, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=542;
UPDATE "recommendations" SET "tmdb_id"=198184, "imdb_id"='tt1823672', "igdb_id"=NULL, "title"='Chappie', "original_title"='Chappie', "media_type"='movie', "release_year"=2015, "poster_url"='https://image.tmdb.org/t/p/w500/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/3pKIcv6KhUE35jsKnv3MylQ3OT2.jpg', "overview"='Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there''s one thing that makes Chappie different from any one else: he is a robot.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.7447, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=1.46677777777777773e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=543;
