UPDATE "recommendations" SET "tmdb_id"=30959, "imdb_id"='tt0058279', "igdb_id"=NULL, "title"='Kwaidan', "original_title"='怪談', "media_type"='movie', "release_year"=1965, "poster_url"='https://image.tmdb.org/t/p/w500/t9UMfViYl47SdZZatKQ1JKjjCgs.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9GAU0z2wVA8M2D2w36CaloWYYgv.jpg', "overview"='Taking its title from an archaic Japanese word meaning "ghost story," this anthology adapts four folk tales. A penniless samurai marries for money with tragic results. A man stranded in a blizzard is saved by Yuki the Snow Maiden, but his rescue comes at a cost. Blind musician Hoichi is forced to perform for an audience of ghosts. An author relates the story of a samurai who sees another warrior''s reflection in his teacup.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.8456, "vote_average"=7.705, "is_ambiguous"=0, "evidence_score"=1.90175000000000018e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=565;
