UPDATE "recommendations" SET "tmdb_id"=97, "imdb_id"='tt0084827', "igdb_id"=NULL, "title"='Tron', "original_title"='Tron', "media_type"='movie', "release_year"=1982, "poster_url"='https://image.tmdb.org/t/p/w500/jigY9B6TKz4qlfikZcd18qtzTK4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vUmeBHiGp5r2ydd8aEvbNLamTVD.jpg', "overview"='When brilliant video game maker Flynn hacks the mainframe of his ex-employer, he is beamed inside an astonishing digital world and becomes part of the very game he is designing. In his mission through cyberspace, Flynn matches wits with a maniacal Master Control Program and teams up with Tron, a security measure created to bring balance to the digital environment.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.8752, "vote_average"=6.627, "is_ambiguous"=0, "evidence_score"=1.61933333333333351e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=774;
UPDATE "recommendations" SET "tmdb_id"=5548, "imdb_id"='tt0093870', "igdb_id"=NULL, "title"='RoboCop', "original_title"='RoboCop', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xcaX6BZ1JUPSVMH2gBkWIckLLaA.jpg', "overview"='In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3779, "vote_average"=7.364, "is_ambiguous"=0, "evidence_score"=2.01877777777777787e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=777;
UPDATE "recommendations" SET "tmdb_id"=9886, "imdb_id"='tt0113481', "igdb_id"=NULL, "title"='Johnny Mnemonic', "original_title"='Johnny Mnemonic', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/iH8Jgi8qvb7pnBfI8fVGaUbyRna.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7FRYVIF2hnh1IbPtqMgF5iygdjz.jpg', "overview"='In a dystopian 2021, Johnny is a data trafficker who has an implant that allows him to securely store data too sensitive for regular computer networks. On one delivery run, he accepts a package that not only exceeds the implant''s safety limits—and will kill him if the data is not removed in time—but also contains information far more important and valuable than he had ever imagined. On a race against time, he must avoid the assassins sent to kill him and remove the data before it, too, ends his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3516, "vote_average"=5.758, "is_ambiguous"=0, "evidence_score"=1.43445454545454538e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=785;
