UPDATE "recommendations" SET "tmdb_id"=412546, "imdb_id"='tt9213244', "igdb_id"=NULL, "title"='Antrum', "original_title"='Antrum', "media_type"='movie', "release_year"=2018, "poster_url"='https://image.tmdb.org/t/p/w500/20de4Rcmy4B0L5zyOc3Nc5F7c0D.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kUfhJUEa4Djx9yCxYCkuEcJFE12.jpg', "overview"='Rumored to have been lost, Antrum appears as a cursed film from the 1970s. Viewers are warned to proceed with caution. It’s said to be a story about a young boy and girl who enter the forest in an attempt to save the soul of their recently deceased pet. They journey to “The Antrum,” the very spot the devil landed after being cast out of heaven. There, the children begin to dig a hole to hell.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6126, "vote_average"=5.763, "is_ambiguous"=0, "evidence_score"=1.21333333333333328e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=976;
