UPDATE "recommendations" SET "tmdb_id"=840430, "imdb_id"='tt14849194', "igdb_id"=NULL, "title"='The Holdovers', "original_title"='The Holdovers', "media_type"='movie', "release_year"=2023, "poster_url"='https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/A99WMiz0ASpH9coOFrxSEuwTWx0.jpg', "overview"='A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.9543, "vote_average"=7.646, "is_ambiguous"=0, "evidence_score"=19.201875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=2373;
UPDATE "recommendations" SET "tmdb_id"=8271, "imdb_id"='tt0486822', "igdb_id"=NULL, "title"='Disturbia', "original_title"='Disturbia', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/3f9KwSrieczuH9nRrwfOsoMoMNd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ve38VxE3qVdk5xbEluWTqFa9oGd.jpg', "overview"='Kale has a life most teenagers would envy. He spends his days endlessly playing video games, surfing the net, eating junk food and watching cable. He has complete free reign of the house, and a beautiful young hottie named Ashley has just moved in next door. There’s only one problem—he’s not allowed to leave the house. Kale’s under court-ordered house arrest for three months, and if he takes one step beyond a 100-foot perimeter of the house, his next confinement will be in a real prison.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.4946, "vote_average"=6.69, "is_ambiguous"=0, "evidence_score"=3.24496666666666655e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-08 02:23:49' WHERE "id"=2386;
