UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=7351, "title"='Doom', "original_title"='Doom', "media_type"='game', "release_year"=2016, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co1nc7.jpg', "backdrop_url"=NULL, "overview"='Developed by id software, the studio that pioneered the first-person shooter genre and created multiplayer Deathmatch, Doom returns as a brutally fun and challenging modern-day shooter experience. Relentless demons, impossibly destructive guns, and fast, fluid movement provide the foundation for intense, first-person combat – whether you’re obliterating demon hordes through the depths of Hell in the single-player campaign, or competing against your friends in numerous multiplayer modes. Expand your gameplay experience using Doom SnapMap game editor to easily create, play, and share your content with the world.', "external_url"='https://www.igdb.com/games/doom--2', "platforms"='["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=4.00333333333333296e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-08 02:23:49' WHERE "id"=3768;
