UPDATE "recommendations" SET "tmdb_id"=32040, "imdb_id"='tt0074749', "igdb_id"=NULL, "title"='The Killing of a Chinese Bookie', "original_title"='The Killing of a Chinese Bookie', "media_type"='movie', "release_year"=1976, "poster_url"='https://image.tmdb.org/t/p/w500/lShPFOAbQ6y6oFYUfecmrj7BUu6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/71oqZMM6dgKvi1WQztOoUHSzDdZ.jpg', "overview"='Cosmo Vittelli, the proprietor of a sleazy, low-rent Hollywood cabaret, has a real affection for the women who strip in his peepshows and the staff who keep up his dingy establishment. He also has a major gambling problem that has gotten him in trouble before. When Cosmo loses big-time at an underground casino run by mobster Mort, he isn''t able to pay up. Mort then offers Cosmo the chance to pay back his debt by knocking off a pesky, Mafia-protected bookie.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6421, "vote_average"=7.032, "is_ambiguous"=0, "evidence_score"=4.02, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-08 02:23:49' WHERE "id"=4038;
