UPDATE "recommendations" SET "tmdb_id"=4587, "imdb_id"='tt0100140', "igdb_id"=NULL, "title"='Mermaids', "original_title"='Mermaids', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/1VufMcp0euY2LpmKiVv8xnbB9Om.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/d4p6VPoN70CnTV74jbW5ltlDgsh.jpg', "overview"='Fifteen-year-old Charlotte Flax is tired of her wacky mom moving their family to a different town any time she feels it is necessary. When they move to a small Massachusetts town and Mrs. Flax begins dating a shopkeeper, Charlotte and her 9-year-old sister, Kate, hope that they can finally settle down. But when Charlotte''s attraction to an older man gets in the way, the family must learn to accept each other for who they truly are.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.9752, "vote_average"=6.721, "is_ambiguous"=0, "evidence_score"=1.10722222222222228e+01, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-08-08 02:23:49' WHERE "id"=5117;
