UPDATE "recommendations" SET "tmdb_id"=5549, "imdb_id"='tt0100502', "igdb_id"=NULL, "title"='RoboCop 2', "original_title"='RoboCop 2', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/nhqBxhOJXUJeFsyLxTFkctH9H5F.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cT0YCYCtAQC8wi56VWK1JRGgk3a.jpg', "overview"='After a successful deployment of the RoboCop Law Enforcement unit, OCP sees its goal of urban pacification come closer and closer, but as this develops, a new narcotic known as "Nuke" invades the streets led by God-delirious leader Cane. As this menace grows, it may prove to be too much for Murphy to handle. OCP tries to replicate the success of the first unit, but ends up with failed prototypes with suicidal issues... until Dr. Faxx, a scientist straying away from OCP''s path, uses Cane as the new subject for the RoboCop 2 project, a living God.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.6071, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-08-03 14:31:56', "updated_at"='2026-08-08 02:23:49' WHERE "id"=6787;
