UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=9727, "title"='Soma', "original_title"='Soma', "media_type"='game', "release_year"=2015, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2a20.jpg', "backdrop_url"=NULL, "overview"='SOMA is a sci-fi horror game from Frictional Games, the creators of Amnesia: The Dark Descent. It is an unsettling story about identity, consciousness, and what it means to be human.

Enter the world of SOMA and face horrors buried deep beneath the ocean waves. Delve through locked terminals and secret documents to uncover the truth behind the chaos. Seek out the last remaining inhabitants and take part in the events that will ultimately shape the fate of the station. But be careful, danger lurks in every corner: corrupted humans, twisted creatures, insane robots, and even an inscrutable omnipresent A.I. You will need to figure out how to deal with each one of them. Just remember there’s no fighting back, either you outsmart your enemies or you get ready to run.', "external_url"='https://www.igdb.com/games/soma', "platforms"='["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=5.03666666666666618e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-08 02:23:49' WHERE "id"=7098;
