UPDATE "recommendations" SET "tmdb_id"=11025, "imdb_id"='tt0363282', "igdb_id"=NULL, "title"='New York Minute', "original_title"='New York Minute', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/px9hV6w6XzAjGdxCRUAUasAHQsP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/13UkK69iyMsB45H2p1WPXJPS87w.jpg', "overview"='Honors student Jane Ryan heads to Manhattan for a college-scholarship competition. Her rebellious twin Roxy tags along to crash a video shoot. But anything can happen – and does – in a romp involving a pursuing truant officer, a smuggler, hunkalicious guys, and the girls'' realization that when the chips are down, a sister can be the best friend of all.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.5527, "vote_average"=6.142, "is_ambiguous"=0, "evidence_score"=2.04, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-08 02:23:49' WHERE "id"=7976;
