UPDATE "recommendations" SET "tmdb_id"=13776, "imdb_id"='tt0083833', "igdb_id"=NULL, "title"='Diner', "original_title"='Diner', "media_type"='movie', "release_year"=1982, "poster_url"='https://image.tmdb.org/t/p/w500/2vKIdZ6JkFIzcQeaHg3xtdvOyRO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/teiop9EWCTTlQ833jrhUPKkK5fs.jpg', "overview"='Set in 1959, Diner shows how five young men resist their adulthood and seek refuge in their beloved Diner. The mundane, childish, and titillating details of their lives are shared. But the golden moments pass, and the men shoulder their responsibilities, leaving the Diner behind.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6419, "vote_average"=6.826, "is_ambiguous"=0, "evidence_score"=3.09666666666666667e+00, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-08 02:23:49' WHERE "id"=8011;
UPDATE "recommendations" SET "tmdb_id"=101519, "imdb_id"='tt2006040', "igdb_id"=NULL, "title"='A Fantastic Fear of Everything', "original_title"='A Fantastic Fear of Everything', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/sMZyKSo8b47VW1h2zjjGUZIefV1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mUWjBk12lY0om9iEFK8wdhxj7It.jpg', "overview"='Jack is a children''s author turned crime novelist whose detailed research into the lives of Victorian serial killers has turned him into a paranoid wreck, persecuted by the irrational fear of being murdered. When Jack is thrown a life-line by his long-suffering agent and a mysterious Hollywood executive takes a sudden and inexplicable interest in his script, what should be his big break rapidly turns into his big breakdown, as Jack is forced to confront his worst demons; among them his love life, his laundry and the origin of all fear.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8555, "vote_average"=5.639, "is_ambiguous"=0, "evidence_score"=2.03, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-08 02:23:49' WHERE "id"=8019;
